/* From Uiverse.io by shadowfax29 - Source: @satyamchaudharydev - Tags: simple, loader, falldown */
.__UIV_SCOPE__ .container {
  position: relative;
  width: 200px;
  height: 200px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 50%;
}

.__UIV_SCOPE__ .loader {
  width: 10px;
  height: 30px;
  left: var(--left);
  border-radius: 10px 50px;
  box-shadow: 0px 0px 5px black;
  animation: dominos 1s ease infinite;
}

.__UIV_SCOPE__ .loader:nth-child(1) {
  --left: 80px;
  animation-delay: 0.325s;
  background-color: red;
}

.__UIV_SCOPE__ .loader:nth-child(3) {
  left: 60px;
  animation-delay: 0.625s;
  background-color: blue;
}

.__UIV_SCOPE__ .loader:nth-child(5) {
  animation-delay: 0.865s;
  left: 40px;
  background-color: green;
}

.__UIV_SCOPE__ .loader:nth-child(2) {
  --left: 70px;
  animation-delay: 0.5s;
  background-color: yellow;
}

.__UIV_SCOPE__ .loader:nth-child(4) {
  animation-delay: 0.74s;
  left: 50px;
  background-color: orange;
}

@keyframes dominos {
  50% {
    opacity: 0.7;
  }

  75% {
    -webkit-transform: rotate(90deg);
    transform: rotate(90deg);
  }

  80% {
    opacity: 1;
  }
}
